/* A disc stream starter and a moby state helper; filed with its sibling FUN_L00_00299460. */
#include "types.h"
#include "rnc/streaming/disc_table.h"
#include "rnc/hero/hero.h"
#include "rnc/globals.h"
#include "asm.h"

void prepare_movie_playback(s32, s32, s32) __asm__("FUN_L00_002995d0");
void hero_respawn() __asm__("FUN_L00_00211250");
/* Picks a disc table entry pair by D_0015ED80 and passes it with the language to FUN_L00_002995d0. */
void start_indexed_disc_stream(s32 i) __asm__("FUN_L02_00298c68");

void start_indexed_disc_stream(s32 i) {
    s32 a, b;
    struct Hero *hero_ptr;
    if (i < 0)
        return;
    if (pal_mode) {
        a = disc_table.unk1A10[i].sector;
        b = disc_table.unk1A10[i].size;
    } else {
        a = disc_table.unk19F8[i].sector;
        b = disc_table.unk19F8[i].size;
    }
    hero_ptr = &hero;
    if (hero_ptr->health.hp == 0) {
        hero_respawn();
    } else if (hero_ptr->fall_fade_pending == 0) {
        prepare_movie_playback(a, b, game_language);
    }
}
#include "eetypes.h"
#include "qcopy.h"
#include "sda.h"
#include "rnc/mobys/moby.h"


extern int process_moby_suck_cannon_suction(void *) __asm__("FUN_L00_002db8f8");

/* Moby state 9 while FUN_L00_002db8f8 reports a hit, back to 1 when it stops. */
int update_moby_suck_cannon_state(struct Moby *a) __asm__("FUN_L02_002d61c0");

int update_moby_suck_cannon_state(struct Moby *moby) {
    int suction_result = process_moby_suck_cannon_suction(moby);
    if (suction_result == 0) {
        if (moby->state == 0x9)
            moby->state = 1;
    } else {
        moby->state = 0x9;
    }
    return suction_result;
}
